const shareAssignmentForGrading = `-- name: ShareAssignmentForGrading :one

SELECT id, course_id, component_id, title, instructions_document_id, rubric_document_id,
       points_possible, due_at, published_at, group_set_id
FROM assignment
WHERE id = $1 AND course_id = $2
FOR SHARE
`

type ShareAssignmentForGradingParams struct {
	ID       uuid.UUID
	CourseID uuid.UUID
}

type ShareAssignmentForGradingRow struct {
	ID                     uuid.UUID
	CourseID               uuid.UUID
	ComponentID            *uuid.UUID
	Title                  string
	InstructionsDocumentID *uuid.UUID
	RubricDocumentID       *uuid.UUID
	PointsPossible         decimal.Decimal
	DueAt                  *time.Time
	PublishedAt            *time.Time
	GroupSetID             *uuid.UUID
}

// Serialising what races -------------------------------------------------------
// The assignment a submission's grade is out of, read again and held still
// until the grade is in. FOR SHARE waits for an assignment.update under way,
// and holds the next one off until the grade is there for its check to find.
// Graders of the same assignment do not wait for one another.
func (q *Queries) ShareAssignmentForGrading(ctx context.Context, arg ShareAssignmentForGradingParams) (ShareAssignmentForGradingRow, error) {
	row := q.db.QueryRow(ctx, shareAssignmentForGrading, arg.ID, arg.CourseID)
	var i ShareAssignmentForGradingRow
	err := row.Scan(
		&i.ID,
		&i.CourseID,
		&i.ComponentID,
		&i.Title,
		&i.InstructionsDocumentID,
		&i.RubricDocumentID,
		&i.PointsPossible,
		&i.DueAt,
		&i.PublishedAt,
		&i.GroupSetID,
	)
	return i, err
}

const studentCountedAsZero = `-- name: StudentCountedAsZero :one
SELECT EXISTS (
    SELECT 1 FROM grade
    WHERE student_member_id = $1 AND origin = 'computed' AND posted_at IS NOT NULL AND superseded_by IS NULL
      AND (breakdown->>'ungraded_as_zero')::boolean IS TRUE
)
`

func (q *Queries) StudentCountedAsZero(ctx context.Context, studentMemberID uuid.UUID) (bool, error) {
	row := q.db.QueryRow(ctx, studentCountedAsZero, studentMemberID)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}

const studentsPostedFromGroupGrade = `-- name: StudentsPostedFromGroupGrade :many
SELECT student_member_id FROM grade
WHERE group_grade_id = $1 AND posted_at IS NOT NULL AND superseded_by IS NULL
ORDER BY 1
`

// The students with a live posted grade given from the group grade.
func (q *Queries) StudentsPostedFromGroupGrade(ctx context.Context, groupGradeID *uuid.UUID) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, studentsPostedFromGroupGrade, groupGradeID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []uuid.UUID
	for rows.Next() {
		var student_member_id uuid.UUID
		if err := rows.Scan(&student_member_id); err != nil {
			return nil, err
		}
		items = append(items, student_member_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const submissionHasGrades = `-- name: SubmissionHasGrades :one
SELECT EXISTS (
    SELECT 1 FROM grade g WHERE g.submission_id = $1::uuid
    UNION ALL
    SELECT 1 FROM group_grade gg WHERE gg.submission_id = $1::uuid
    UNION ALL
    SELECT 1 FROM action x
    WHERE x.target_type = 'submission' AND x.target_id = $1::uuid
      AND x.action_type = 'grade.submit' AND x.status = 'proposed'
)
`

// A grade entered, or proposed and not yet decided: either way, one is on its
// way for exactly this work. A group grade is entered with its members'.
func (q *Queries) SubmissionHasGrades(ctx context.Context, submissionID *uuid.UUID) (bool, error) {
	row := q.db.QueryRow(ctx, submissionHasGrades, submissionID)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}

